+function isWeakText(value) {
+  const text = String(value || "").trim().toLowerCase();
+  if (!text) return true;
+  if (text.length < 20) return true;
+  const weakPatterns = [
+    /^shop\s+$/i,
+    /^buy\s+$/i,
+    /^high[- ]quality$/i,
+    /^premium$/i,
+    /^best seller$/i,
+    /^new arrival$/i,
+    /^perfect for$/i,
+    /^must[- ]have$/i,
+    /^discover$/i,
+    /^browse$/i,
+    /^free shipping$/i,
+  ];
+  const words = text.split(/\s+/);
+  return words.every((word) => weakPatterns.some((pattern) => pattern.test(word)));
+}
