+  const variableFile = path.join(tempDir, "variables.json");
+  const outputFile = path.join(tempDir, "output.json");
+  try {
+    await fs.writeFile(queryFile, query, "utf8");
+    await fs.writeFile(variableFile, JSON.stringify(variables || {}), "utf8");
+    const args = [
+      cliJs,
+      "store",
+      "execute",
+      "--store",
+      shop,
+      "--query-file",
+      queryFile,
+      "--variable-file",
+      variableFile,
+      "--output-file",
+      outputFile,
+      "--json",
+      "--no-color",
