+    .catch(() => "");
+  const match = html.match(/(?:Shopify\.shop|myshopify(?:_domain|Domain)|permanent(?:_domain|Domain))\s*[:=]\s*["']([^"']+\.myshopify\.com)["']/i)
+    || html.match(/https?:\\?\/\\?\/([a-z0-9-]+\.myshopify\.com)/i);
+  if (match?.[1]) return match[1].toLowerCase();
